MAP
    NAME "SS_MAP_AGUA_LINKS"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_links.log"
    DEBUG 0
    LAYER
        NAME "SS_MAP_AGUA_LINKS_INFO"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        CONNECTIONTYPE POSTGIS
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from (select gid,geometry,CAST(TO_CHAR(diametro, 'FM990.999') as double precision) as diametro from links where tipo = 1) as tmp using unique gid using srid=32614"
        TYPE line
        MINSCALE 1
        MAXSCALE 15000
        LABELITEM "diametro"
        CLASS
            LABEL
                ANGLE AUTO
                PARTIALS FALSE
                SIZE 18
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
                TYPE TRUETYPE
                FONT 'arial'
            END #LABEL
        END #CLASS
    END #LAYER
    LAYER
        NAME "SS_MAP_AGUA_LINKS_TUBERIA"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        CONNECTIONTYPE POSTGIS
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from links using unique gid using srid=32614"
        TYPE line
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            NAME "TUBERIA"
            STYLE
                COLOR 0 0 0
                WIDTH 5.0
            END #STYLE
            STYLE
                COLOR 0 147 221
                WIDTH 3.0
            END #STYLE
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_AGUA_LINKS_UBICACION"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from (select gid,st_centroid(geometry) as geometry,tipo from links where tipo =2 or tipo = 3) as tmp using unique gid using srid=32614"
        TYPE POINT
        MINSCALE 1
        MAXSCALE 15000
        CLASSITEM "tipo"
        CLASS
            NAME "BOMBA"
            EXPRESSION "2"
            STYLE
                SYMBOL "bomba"
                SIZE 14
            END #STYLE
        END #CLASS
        CLASS
            NAME "VALVULA"
            EXPRESSION "3"
            STYLE
                SYMBOL "valvula"
                SIZE 14
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP

